// One outcome per LinkedIn call. Only an explicit LinkedIn refusal (4xx other than timeout) counts as failed;
// anything ambiguous is 'unknown' so the database blocks a blind retry until someone reconciles it.
const claim = $('Claim Publish Slot').first().json;
return $input.all().map((it, i) => {
  const j = it.json || {};
  let outcome = 'unknown', urn = '', url = '', err = '';
  if (j.error) {
    const e = j.error;
    const msg = typeof e === 'string' ? e : String(e.message || e.description || JSON.stringify(e));
    const code = Number((typeof e === 'object' && (e.httpCode || e.statusCode || e.status)) || j.httpCode || 0) || 0;
    outcome = code >= 400 && code < 500 && code !== 408 ? 'failed' : 'unknown';
    err = (code ? 'HTTP ' + code + ': ' : 'No HTTP status available: ') + msg;
  } else if (j.urn) {
    outcome = 'published';
    urn = String(j.urn);
    url = 'https://www.linkedin.com/feed/update/' + urn;
  } else {
    err = 'LinkedIn returned no post URN, so it is unclear whether the post went out.';
  }
  return { json: { outcome, linkedin_urn: urn, post_url: url, error_details: err.slice(0, 2000), attempt_id: claim.attempt_id, content_id: claim.content_id, destination: claim.destination }, pairedItem: { item: i } };
});

